import java.util.*;

public class Main {
    static final int N = 10;
    static String[] grid = new String[N];
    static int[][] n_scientists = new int[N][N];
    static int[][] n_rescue = new int[N][N];
    static int[][] infect_time = new int[N][N];
    static int[] delta_x = {-1, 1, 0, 0};
    static int[] delta_y = {0, 0, -1, 1};
    static int[][][][] reach_time = new int[N][N][N][N];
    static final int MAX_FLOW = 2 * N * N + 2;
    static final int INF = 1000000000;
    static List<Integer>[] adj = new ArrayList[MAX_FLOW + 1];
    static int[][] capacity = new int[MAX_FLOW][MAX_FLOW];
    static int[][] flow = new int[MAX_FLOW][MAX_FLOW];
    static int[] ptr = new int[MAX_FLOW];
    static int[] dist = new int[MAX_FLOW];
    static int[] parent = new int[MAX_FLOW];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < N; i++) {
            adj[i] = new ArrayList<>();
        }
        int n = sc.nextInt();
        int t = sc.nextInt();
        sc.nextLine();
        int explosionX = -1, explosionY = -1;
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            grid[i] = line;
            for (int j = 0; j < n; j++) {
                if (line.charAt(j) == 'Y') {
                    // do nothing, grid[i][j] == 'Y'
                } else if (line.charAt(j) == 'Z') {
                    explosionX = i;
                    explosionY = j;
                } else {
                    n_scientists[i][j] += line.charAt(j) - '0';
                }
            }
        }
        String line2 = sc.nextLine();
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < n; j++) {
                if (line.charAt(j) != 'Y' && line.charAt(j) != 'Z') {
                    n_rescue[i][j] += line.charAt(j) - '0';
                }
            }
        }
        for (int i = 0; i < N; i++) {
            Arrays.fill(infect_time[i], -1);
        }
        infect_time[explosionX][explosionY] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{explosionX, explosionY});
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int i = curr[0], j = curr[1];
            for (int d = 0; d < 4; d++) {
                int ni = i + delta_x[d], nj = j + delta_y[d];
                if (0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni].charAt(nj) == '.' && infect_time[ni][nj] == -1) {
                    infect_time[ni][nj] = infect_time[i][j] + 1;
                    q.offer(new int[]{ni, nj});
                }
            }
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                Arrays.fill(reach_time[i][j], new int[N][N]);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i].charAt(j) == '.') {
                    for (int ii = 0; ii < n; ii++) {
                        for (int jj = 0; jj < n; jj++) {
                            reach_time[i][j][ii][jj] = -1;
                        }
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i].charAt(j) == '.') {
                    reach_time[i][j][i][j] = 0;
                    Queue<int[]> q2 = new LinkedList<>();
                    q2.offer(new int[]{i, j});
                    while (!q2.isEmpty()) {
                        int[] curr = q2.poll();
                        int ii = curr[0], jj = curr[1];
                        if (infect_time[ii][jj] == -1 || reach_time[i][j][ii][jj] < infect_time[ii][jj]) {
                            for (int d = 0; d < 4; d++) {
                                int ni = ii + delta_x[d], nj = jj + delta_y[d];
                                if (0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni].charAt(nj) == '.') {
                                    if (infect_time[ni][nj] == -1 || reach_time[i][j][ii][jj] + 1 <= infect_time[ni][nj]) {
                                        if (reach_time[i][j][ni][nj] == -1) {
                                            reach_time[i][j][ni][nj] = reach_time[i][j][ii][jj] + 1;
                                            q2.offer(new int[]{ni, nj});
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        int s_node = 2 * n * n;
        int t_node = 2 * n * n + 1;
        setup_network();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (n_scientists[i][j] > 0) {
                    add_network_edge(s_node, node_id(n, i, j, false), n_scientists[i][j]);
                }
                if (n_rescue[i][j] > 0) {
                    add_network_edge(node_id(n, i, j, true), t_node, n_rescue[i][j]);
                }
                for (int ii = 0; ii < n; ii++) {
                    for (int jj = 0; jj < n; jj++) {
                        if (reach_time[i][j][ii][jj] != -1 && reach_time[i][j][ii][jj] <= t) {
                            add_network_edge(node_id(n, i, j, false), node_id(n, ii, jj, true), INF);
                        }
                    }
                }
            }
        }
        System.out.println(max_flow(s_node, t_node));
        sc.close();
    }

    static int node_id(int n, int i, int j, boolean right) {
        return i * n + j + (right ? n * n : 0);
    }

    static void setup_network() {
        for (int i = 0; i <= MAX_FLOW; i++) {
            adj[i].clear();
        }
        for (int u = 0; u < MAX_FLOW; u++) {
            Arrays.fill(capacity[u], 0);
            Arrays.fill(flow[u], 0);
        }
    }

    static void add_network_edge(int u, int v, int c) {
        adj[u].add(v);
        adj[v].add(u);
        capacity[u][v] += c;
    }

    static int max_flow(int s, int t) {
        int total = 0;
        while (build_graph(s, t)) {
            Arrays.fill(ptr, 0);
            while (find_path(s, t)) {
                int min_cap = INF;
                for (int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                    min_cap = Math.min(min_cap, capacity[u][v] - flow[u][v]);
                }
                for (int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                    flow[u][v] += min_cap;
                    flow[v][u] -= min_cap;
                }
                total += min_cap;
            }
        }
        return total;
    }

    static boolean build_graph(int s, int t) {
        Arrays.fill(dist, -1);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (capacity[u][v] - flow[u][v] > 0 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                }
            }
        }
        return dist[t] != -1;
    }

    static boolean find_path(int u, int t) {
        Arrays.fill(parent, -1);
        parent[u] = 0;
        return dfs_path(u, t);
    }

    static boolean dfs_path(int u, int t) {
        if (u == t) return true;
        for (int i = ptr[u]; i < adj[u].size(); i++) {
            int v = adj[u].get(i);
            if (dist[v] == dist[u] + 1 && capacity[u][v] - flow[u][v] > 0 && dfs_path(v, t)) {
                parent[v] = u;
                return true;
            }
            ptr[u]++;
        }
        return false;
    }
}
